//! Phase 2i / 2j: capability confidence intervals, additional distributions,
//! empirical-percentile capability, the extended sixpack, gage linearity and
//! bias, and attribute agreement — checked against independent NumPy/SciPy
//! computations (`common/data9.rs`, generated by `gen/stats_ref9.py`).

mod common;
use common::data9::*;
use openstats_math::dist::{ContinuousDistribution, Exponential};
use openstats_stats::capability::*;
use openstats_stats::msa::{AttributeOptions, AttributeStudy, LinearityBiasOptions, LinearityBiasStudy};
use openstats_stats::report::{Reportable, SessionReport};
use openstats_stats::spc::sixpack::SixpackOptions;

fn close(a: f64, b: f64, tol: f64, what: &str) {
    assert!((a - b).abs() <= tol * b.abs().max(1.0), "{what}: {a} vs {b}");
}

fn same_json(r: &SessionReport) {
    r.validate().unwrap();
    assert_eq!(SessionReport::from_json(&r.to_json()).unwrap().to_json(), r.to_json());
    assert!(!r.render_text().is_empty());
}

#[test]
fn capability_intervals_match_scipy() {
    let r = CI_REF;
    let specs = Specs::two_sided(r[0], r[1]).with_target(r[2]);
    let c = capability_individuals(CI_DATA, &specs, &CapabilityOptions::default()).unwrap();
    let ci = capability_intervals(&c, None, 0.95).unwrap();
    let (l, u) = (ci.ppl.unwrap(), ci.ppu.unwrap());
    close(l.lower, r[3], 1e-7, "ppl lo");
    close(l.upper, r[4], 1e-7, "ppl hi");
    close(u.lower, r[5], 1e-7, "ppu lo");
    close(u.upper, r[6], 1e-7, "ppu hi");
    let p = ci.pp.unwrap();
    close(p.lower, r[7], 1e-10, "pp lo");
    close(p.upper, r[8], 1e-10, "pp hi");
    close(ci.ppk.lower, r[9], 1e-10, "ppk lo");
    close(ci.ppk.upper, r[10], 1e-10, "ppk hi");
    let m = ci.cpm.unwrap();
    close(m.lower, r[11], 1e-10, "cpm lo");
    close(m.upper, r[12], 1e-10, "cpm hi");
    assert!(ci.cp.is_none() && ci.cpk.is_none() && ci.within_df.is_none());
    // Estimates lie inside their intervals; the one-sided limits bracket the estimate.
    assert!(l.lower < c.ppl.unwrap() && c.ppl.unwrap() < l.upper);
    assert!(u.lower < c.ppu.unwrap() && c.ppu.unwrap() < u.upper);
}

#[test]
fn within_intervals_use_the_supplied_degrees_of_freedom() {
    let r = CI_REF;
    let w = CI_WITHIN_REF;
    let specs = Specs::two_sided(r[0], r[1]).with_target(r[2]);
    let c = capability_individuals(CI_DATA, &specs, &CapabilityOptions::default()).unwrap();
    close(c.sd_within, w[1], 1e-12, "sd within");
    let ci = capability_intervals(&c, Some(w[0]), 0.90).unwrap();
    close(ci.cpl.unwrap().lower, w[2], 1e-7, "cpl lo");
    close(ci.cpl.unwrap().upper, w[3], 1e-7, "cpl hi");
    close(ci.cpu.unwrap().lower, w[4], 1e-7, "cpu lo");
    close(ci.cpu.unwrap().upper, w[5], 1e-7, "cpu hi");
    close(ci.cp.unwrap().lower, w[6], 1e-10, "cp lo");
    close(ci.cp.unwrap().upper, w[7], 1e-10, "cp hi");
    close(ci.cpk.unwrap().lower, w[8], 1e-10, "cpk lo");
    close(ci.cpk.unwrap().upper, w[9], 1e-10, "cpk hi");
    // A wider confidence level gives a wider interval.
    let narrow = capability_intervals(&c, Some(w[0]), 0.80).unwrap();
    assert!(narrow.cpu.unwrap().upper - narrow.cpu.unwrap().lower < ci.cpu.unwrap().upper - ci.cpu.unwrap().lower);
    assert!(capability_intervals(&c, Some(-1.0), 0.9).is_err());
    assert!(capability_intervals(&c, None, 1.0).is_err());
}

#[test]
fn pooled_df_counts_observations_minus_subgroups() {
    let g = vec![vec![1.0, 2.0, 3.0], vec![2.0, 2.5], vec![1.0, f64::NAN, 4.0]];
    assert_eq!(pooled_within_df(&g).unwrap(), 4.0);
    assert!(pooled_within_df(&[vec![1.0]]).is_err());
}

#[test]
fn new_families_match_scipy_mle() {
    let r = FIT_REF;
    let e = fit_distribution(FIT_POS, Family::Exponential, None).unwrap();
    close(e.param1, r[0], 1e-12, "exp scale");
    close(e.log_likelihood, r[1], 1e-10, "exp ll");
    assert!(e.param2.is_nan());
    let g = fit_distribution(FIT_POS, Family::Logistic, None).unwrap();
    close(g.param1, r[2], 1e-5, "logistic loc");
    close(g.param2, r[3], 1e-5, "logistic scale");
    close(g.log_likelihood, r[4], 1e-8, "logistic ll");
    let l = fit_distribution(FIT_POS, Family::Loglogistic, None).unwrap();
    close(l.param1, r[5], 1e-5, "loglogistic mu");
    close(l.param2, r[6], 1e-5, "loglogistic sigma");
    close(l.log_likelihood, r[7], 1e-8, "loglogistic ll");
    let n = fit_distribution(FIT_POS, Family::Normal, None).unwrap();
    close(n.param1, r[8], 1e-12, "normal mean");
    close(n.param2, r[9], 1e-12, "normal sd");
    close(n.log_likelihood, r[10], 1e-10, "normal ll");
    // Shifted exponential.
    let t = FIT_EXP_THR_REF;
    let s = fit_distribution(FIT_EXP_THR, Family::Exponential, Some(t[0])).unwrap();
    close(s.param1, t[1], 1e-12, "shifted exp scale");
    close(s.log_likelihood, t[2], 1e-10, "shifted exp ll");
    // The threshold is irrelevant to the location-scale families and ignored.
    let n2 = fit_distribution(FIT_POS, Family::Normal, Some(1e9)).unwrap();
    assert_eq!(n2.threshold, 0.0);
    assert!(fit_distribution(FIT_EXP_THR, Family::Exponential, Some(100.0)).is_err());
    assert!(fit_distribution(&[1.0, 1.0, 1.0], Family::Logistic, None).is_err());
}

#[test]
fn exponential_capability_uses_closed_form_percentiles() {
    let specs = Specs::two_sided(0.5, 60.0);
    let c = capability_distribution(
        FIT_EXP_THR,
        Family::Exponential,
        Some(FIT_EXP_THR_REF[0]),
        &Specs::two_sided(5.0, 40.0),
    )
    .unwrap();
    let d = Exponential::new(FIT_EXP_THR_REF[1], FIT_EXP_THR_REF[0]).unwrap();
    close(c.x_high, d.quantile(1.0 - 0.001349898031630094), 1e-9, "x_high");
    close(c.median, d.quantile(0.5), 1e-12, "median");
    close(c.expected.ppm_above, d.sf(40.0) * 1e6, 1e-9, "ppm above");
    assert!(capability_distribution(FIT_POS, Family::Exponential, None, &specs).is_ok());
    // Normal "distribution capability" equals the percentile form with the MLE σ.
    let n = capability_distribution(FIT_POS, Family::Normal, None, &specs).unwrap();
    let f = fit_distribution(FIT_POS, Family::Normal, None).unwrap();
    close(n.pp.unwrap(), (60.0 - 0.5) / (6.0 * f.param2), 1e-6, "normal pp");
}

#[test]
fn identification_ranks_the_candidates() {
    let ranks = identify_distributions(FIT_POS, None).unwrap();
    assert!(ranks.len() >= 7, "{ranks:?}");
    assert!(ranks.windows(2).all(|w| w[0].ad <= w[1].ad));
    let pos = |name: &str| ranks.iter().position(|r| r.name == name).unwrap();
    // The data are Weibull(2.2, 14): Weibull beats exponential and logistic.
    assert!(pos("Weibull") < pos("Exponential") && pos("Weibull") < pos("Logistic"));
    let normal = &ranks[pos("Normal")];
    assert!(normal.p_value.is_some() && normal.log_likelihood.is_some());
    assert!(ranks.iter().any(|r| r.name.starts_with("Johnson") && r.family.is_none() && r.parameters == 4));
    // Data below the default threshold leave only the families without one.
    let neg: Vec<f64> = FIT_POS.iter().map(|v| v - 20.0).collect();
    let r = identify_distributions(&neg, None).unwrap();
    assert!(r.iter().any(|x| x.name == "Normal") && !r.iter().any(|x| x.name == "Weibull"));
    assert!(identify_distributions(&[1.0, 1.0], None).is_err());
}

#[test]
fn empirical_percentiles_match_numpy_type6() {
    let r = EMP_REF;
    let c = capability_empirical(EMP_DATA, &Specs::two_sided(r[0], r[1]), &EmpiricalOptions::default()).unwrap();
    close(c.x_low, r[2], 1e-10, "p0.135");
    close(c.median, r[3], 1e-12, "median");
    close(c.x_high, r[4], 1e-10, "p99.865");
    close(c.pp.unwrap(), r[5], 1e-10, "pp");
    close(c.ppl.unwrap(), r[6], 1e-10, "ppl");
    close(c.ppu.unwrap(), r[7], 1e-10, "ppu");
    close(c.ppk, r[8], 1e-10, "ppk");
    assert_eq!(c.observed.n_below as f64, r[9]);
    assert_eq!(c.observed.n_above as f64, r[10]);
    assert!(c.notes.is_empty());
    same_json(&c.to_report("Empirical capability"));
}

#[test]
fn empirical_percentiles_need_enough_data() {
    let small: Vec<f64> = (1..=200).map(|i| i as f64).collect();
    let specs = Specs::two_sided(-10.0, 300.0);
    assert!(capability_empirical(&small, &specs, &EmpiricalOptions::default()).is_err());
    let c =
        capability_empirical(&small, &specs, &EmpiricalOptions { allow_extremes: true, ..Default::default() }).unwrap();
    assert_eq!((c.x_low, c.x_high), (1.0, 200.0));
    assert_eq!(c.notes.len(), 1);
    assert!(capability_empirical(&[1.0, 2.0], &specs, &EmpiricalOptions::default()).is_err());
    assert!(capability_empirical(EMP_DATA, &Specs::default(), &EmpiricalOptions::default()).is_err());
}

#[test]
fn subgroup_capability_and_running_average() {
    let groups: Vec<Vec<f64>> = vec![vec![9.0, 10.0, 11.0], vec![10.0, 10.5, 11.5, 11.0], vec![8.0, 8.0, 8.0]];
    let specs = Specs::two_sided(4.0, 16.0);
    let v = capability_by_subgroup(&groups, &specs).unwrap();
    assert_eq!(v.len(), 3);
    // Subgroup 1: mean 10, sd 1 → Ppk = 6/3 = 2, Pp = 12/6 = 2.
    close(v[0].ppk.unwrap(), 2.0, 1e-12, "ppk 1");
    close(v[0].pp.unwrap(), 2.0, 1e-12, "pp 1");
    assert!(v[2].ppk.is_none() && v[2].pp.is_none(), "zero-variance subgroup has no index");
    let ra = running_average(&groups, 0.9, 3.0).unwrap();
    assert_eq!(ra.count, vec![3, 7, 10]);
    close(ra.mean[0], 10.0, 1e-12, "mean 1");
    close(ra.mean[1], (30.0 + 43.0) / 7.0, 1e-12, "mean 2");
    close(ra.center, (30.0 + 43.0 + 24.0) / 10.0, 1e-12, "centre");
    close(ra.upper[1] - ra.lower[1], 2.0 * 3.0 * 0.9 / 7.0f64.sqrt(), 1e-12, "limit width");
    assert!(ra.upper[0] - ra.lower[0] > ra.upper[2] - ra.lower[2]);
    assert!(running_average(&groups, 0.0, 3.0).is_err() && running_average(&groups, 1.0, 0.0).is_err());
}

#[test]
fn extended_sixpack_adds_two_panels() {
    let d: Vec<f64> = (0..60).map(|i| 50.0 + (((i * 17) % 23) as f64 - 11.0) * 0.1).collect();
    let specs = Specs::two_sided(48.0, 52.0).with_target(50.0);
    let groups: Vec<Vec<f64>> = d.chunks(5).map(<[f64]>::to_vec).collect();
    let s = extended_sixpack_subgroups(&groups, &specs, &SixpackOptions::default()).unwrap();
    let ch = s.charts();
    assert_eq!(ch.len(), 8);
    assert_eq!(ch[6].title, "Capability by Subgroup");
    assert_eq!(ch[6].series.len(), 2);
    assert_eq!(ch[7].title, "Running Average Chart");
    assert_eq!(ch[7].series[0].x.len(), 12);
    assert!(s.within_df.is_none());
    same_json(&s.to_report("Extended sixpack"));
    let pooled = extended_sixpack_subgroups(
        &groups,
        &specs,
        &SixpackOptions {
            capability: CapabilityOptions {
                subgroup_sigma: Some(openstats_stats::spc::charts::SubgroupSigma::Pooled),
                ..Default::default()
            },
            ..Default::default()
        },
    )
    .unwrap();
    assert_eq!(pooled.within_df, Some(48.0));
    let ci = capability_intervals(pooled.capability(), pooled.within_df, 0.95).unwrap();
    assert!(ci.cp.is_some());
    let ind = extended_sixpack_individuals(&d, &specs, &SixpackOptions::default(), 5).unwrap();
    assert_eq!(ind.by_subgroup.len(), 12);
    assert_eq!(ind.running_average.count.len(), 60);
    assert!(extended_sixpack_individuals(&d, &specs, &SixpackOptions::default(), 1).is_err());
    same_json(&ind.to_report("Extended sixpack individuals"));
}

#[test]
fn interval_report_and_ranking_sections_round_trip() {
    let specs = Specs::two_sided(CI_REF[0], CI_REF[1]).with_target(CI_REF[2]);
    let c = capability_individuals(CI_DATA, &specs, &CapabilityOptions::default()).unwrap();
    let ci = capability_intervals(&c, Some(31.0), 0.95).unwrap();
    let mut r = SessionReport::new("Capability");
    r.push(intervals_section(&c, &ci));
    r.push(ranking_section(&identify_distributions(FIT_POS, None).unwrap()));
    same_json(&r);
    assert_eq!(r.sections.len(), 2);
}

