#[test]
fn linearity_and_bias_match_scipy() {
    let study = LinearityBiasStudy::new(LB_REF, LB_MEAS).unwrap();
    let r = study.analyze(&LinearityBiasOptions { process_variation: 6.0, level: 0.95 }).unwrap();
    let x = LB_RES;
    let g = &r.regression;
    close(g.slope.coef, x[0], 1e-10, "slope");
    close(g.slope.se, x[1], 1e-10, "slope se");
    close(g.slope.p, x[2], 1e-8, "slope p");
    close(g.intercept.coef, x[3], 1e-10, "intercept");
    close(g.intercept.se, x[4], 1e-10, "intercept se");
    close(g.intercept.t, x[5], 1e-10, "intercept t");
    close(g.intercept.p, x[6], 1e-8, "intercept p");
    close(g.s, x[7], 1e-10, "S");
    close(g.r_squared.unwrap(), x[8], 1e-10, "R²");
    close(g.slope.ci.upper - g.slope.coef, x[9] * x[1], 1e-9, "slope ci half width");
    close(r.linearity, x[10], 1e-10, "linearity");
    close(r.pct_linearity, x[11], 1e-10, "% linearity");
    close(r.average_bias.bias, x[12], 1e-10, "average bias");
    close(r.average_bias.pct_bias, x[13], 1e-10, "% average bias");
    close(r.average_bias.t.unwrap(), x[14], 1e-9, "average t");
    close(r.average_bias.p.unwrap(), x[15], 1e-8, "average p");
    assert_eq!(g.df, 48);
    assert_eq!(r.biases.len(), 5);
    for (i, b) in r.biases.iter().enumerate() {
        let o = &LB_BIAS_ROWS[5 * i..5 * i + 5];
        assert_eq!(b.reference.unwrap(), o[0]);
        close(b.bias, o[1], 1e-10, "bias");
        close(b.pct_bias, o[2], 1e-10, "% bias");
        close(b.t.unwrap(), o[3], 1e-9, "t");
        close(b.p.unwrap(), o[4], 1e-8, "p");
        assert_eq!(b.n, 10);
    }
    let ch = r.chart_spec();
    assert_eq!(ch.series.len(), 5);
    assert_eq!(ch.series[3].x.len(), 50);
    assert!(r.band.iter().all(|b| b[2] < b[1] && b[1] < b[3]));
    same_json(&r.to_report("Linearity and bias"));
}

#[test]
fn linearity_validation_and_edge_cases() {
    let o = LinearityBiasOptions { process_variation: 6.0, level: 0.95 };
    assert!(LinearityBiasStudy::new(&[1.0, 2.0], &[1.0]).is_err());
    let one_ref = LinearityBiasStudy::new(&[5.0, 5.0, 5.0, 5.0], &[5.1, 4.9, 5.2, 5.0]).unwrap();
    assert!(one_ref.analyze(&o).is_err());
    assert!(LinearityBiasStudy::new(&[1.0, 2.0], &[1.0, 2.0]).unwrap().analyze(&o).is_err());
    let s = LinearityBiasStudy::new(&[1.0, 1.0, 2.0, 2.0, 3.0, f64::NAN], &[1.1, 0.9, 2.2, 1.8, 3.3, 1.0]).unwrap();
    assert!(s.analyze(&LinearityBiasOptions { process_variation: 0.0, ..o }).is_err());
    assert!(s.analyze(&LinearityBiasOptions { level: 1.5, ..o }).is_err());
    let r = s.analyze(&o).unwrap();
    assert_eq!(r.n, 5);
    // A single measurement of a reference has no test.
    assert!(r.biases[2].p.is_none() && r.biases[2].n == 1);
    // A perfect gage (zero bias everywhere) has zero linearity.
    let perfect = LinearityBiasStudy::new(&[1.0, 2.0, 3.0, 4.0], &[1.0, 2.0, 3.0, 4.0]).unwrap().analyze(&o).unwrap();
    assert_eq!(perfect.linearity, 0.0);
    assert!(perfect.regression.r_squared.is_none());
}

fn att_study() -> AttributeStudy {
    AttributeStudy::from_long(ATT_SAMPLE, ATT_APPRAISER, ATT_RATING, Some(ATT_STANDARD)).unwrap()
}

#[test]
fn attribute_agreement_matches_numpy() {
    let opts = AttributeOptions { level: 0.95, defect_category: Some("bad".into()) };
    let r = att_study().analyze(&opts).unwrap();
    assert_eq!((r.samples, r.trials, r.appraisers.len()), (24, 3, 3));
    assert_eq!(r.categories, vec!["bad", "good"]);
    for a in 0..3 {
        let w = &ATT_WITHIN[6 * a..6 * a + 6];
        let g = &r.within[a];
        assert_eq!(g.agreement.matched as f64, w[0]);
        close(g.agreement.percent, w[1], 1e-12, "within %");
        close(g.agreement.ci.lower, w[2], 1e-9, "within ci lo");
        close(g.agreement.ci.upper, w[3], 1e-9, "within ci hi");
        let k = &g.kappa.as_ref().unwrap()[0];
        assert_eq!(k.category, "Overall");
        close(k.kappa, w[4], 1e-10, "within kappa");
        close(k.se, w[5], 1e-10, "within se");
        let v = &ATT_VS_STD[13 * a..13 * a + 13];
        let s = &r.vs_standard.as_ref().unwrap()[a];
        assert_eq!(s.agreement.matched as f64, v[0]);
        close(s.agreement.ci.lower, v[2], 1e-9, "std ci lo");
        close(s.agreement.ci.upper, v[3], 1e-9, "std ci hi");
        close(s.kappa.kappa, v[4], 1e-10, "cohen kappa");
        close(s.kappa.p_observed, v[5], 1e-12, "po");
        close(s.kappa.p_expected, v[6], 1e-12, "pe");
        close(s.kappa.se, v[7], 2e-5, "non-null se (delta method)");
        let d = s.disagreement.as_ref().unwrap();
        assert_eq!(d.misses as f64, v[8]);
        close(d.miss_rate.unwrap(), v[9], 1e-12, "miss rate");
        assert_eq!(d.false_alarms as f64, v[10]);
        close(d.false_alarm_rate.unwrap(), v[11], 1e-12, "false alarm rate");
        assert_eq!(d.mixed as f64, v[12]);
        assert_eq!(s.kappa_by_category.len(), 2);
    }
    let b = &r.between;
    assert_eq!(b.agreement.matched as f64, ATT_BETWEEN[0]);
    close(b.agreement.ci.lower, ATT_BETWEEN[2], 1e-9, "between ci lo");
    close(b.kappa[0].kappa, ATT_BETWEEN[4], 1e-10, "between kappa");
    close(b.kappa[0].se, ATT_BETWEEN[5], 1e-10, "between se");
    let (a, k) = r.all_vs_standard.as_ref().unwrap();
    assert_eq!(a.matched as f64, ATT_ALL_STD[0]);
    close(a.ci.upper, ATT_ALL_STD[3], 1e-9, "all vs std ci hi");
    close(k.kappa, ATT_ALL_STD[4], 1e-10, "all vs std kappa");
    assert_eq!(r.pairs.len(), 3);
    for (i, p) in r.pairs.iter().enumerate() {
        close(p.kappa.kappa, ATT_PAIRS[2 * i], 1e-10, "pair kappa");
        close(p.kappa.se, ATT_PAIRS[2 * i + 1], 2e-5, "pair se");
        assert!(p.kappa.ci.lower < p.kappa.kappa && p.kappa.kappa < p.kappa.ci.upper);
    }
    assert_eq!(r.charts().len(), 2);
    same_json(&r.to_report("Attribute agreement"));
}

#[test]
fn attribute_agreement_without_standard_and_validation() {
    let s = AttributeStudy::from_long(ATT_SAMPLE, ATT_APPRAISER, ATT_RATING, None).unwrap();
    let r = s.analyze(&AttributeOptions::default()).unwrap();
    assert!(r.vs_standard.is_none() && r.all_vs_standard.is_none());
    assert_eq!(r.charts().len(), 1);
    assert!(s.analyze(&AttributeOptions { defect_category: Some("bad".into()), ..Default::default() }).is_err());
    assert!(att_study()
        .analyze(&AttributeOptions { defect_category: Some("nope".into()), ..Default::default() })
        .is_err());
    assert!(att_study().analyze(&AttributeOptions { level: 0.0, ..Default::default() }).is_err());
    // Unbalanced and inconsistent designs.
    assert!(AttributeStudy::from_long(&["a", "a", "b"], &["x", "x", "x"], &["g", "g", "g"], None).is_err());
    assert!(AttributeStudy::from_long(&["a", "a"], &["x", "x"], &["g", "g"], Some(&["g", "b"])).is_err());
    assert!(AttributeStudy::from_long(&["a"], &["x", "y"], &["g"], None).is_err());
    assert!(AttributeStudy::from_long(&[], &[], &[], None).is_err());
    same_json(&r.to_report("No standard"));
}

#[test]
fn perfect_and_constant_ratings() {
    // Everyone agrees with the standard: 100 % matched, κ = 1 (or undefined with one category).
    let sample: Vec<&str> = ["s1", "s1", "s2", "s2", "s3", "s3", "s4", "s4"].to_vec();
    let appraiser = vec!["A"; 8];
    let rating = ["p", "p", "f", "f", "p", "p", "f", "f"];
    let r = AttributeStudy::from_long(&sample, &appraiser, &rating, Some(&rating))
        .unwrap()
        .analyze(&AttributeOptions { level: 0.9, defect_category: Some("f".into()) })
        .unwrap();
    let v = &r.vs_standard.as_ref().unwrap()[0];
    assert_eq!(v.agreement.percent, 100.0);
    assert!((v.kappa.kappa - 1.0).abs() < 1e-12);
    assert_eq!(v.disagreement.as_ref().unwrap().miss_rate, Some(0.0));
    assert!((r.within[0].kappa.as_ref().unwrap()[0].kappa - 1.0).abs() < 1e-12);
    // A single category everywhere leaves κ undefined (NaN), and the report copes.
    let one = ["p"; 8];
    let r = AttributeStudy::from_long(&sample, &appraiser, &one, None)
        .unwrap()
        .analyze(&AttributeOptions::default())
        .unwrap();
    assert!(r.within[0].kappa.as_ref().unwrap()[0].kappa.is_nan());
    same_json(&r.to_report("Constant"));
}
